"""Readable Markdown report of the Best-of-N analysis."""
from __future__ import annotations

from eotts.bon.select import RULES

RULE_NAME = {"v1": "V1 RemoteCLIP-B/32", "v2": "V2 GeoRSCLIP-L/14", "v1+v2": "V1+V2 rank average"}


def _ci(d, scale=1.0, digits=4):
    f = f"{{:+.{digits}f}}"
    return f"{f.format(d['estimate'] * scale)} [{f.format(d['ci_low'] * scale)}, {f.format(d['ci_high'] * scale)}]"


def write_report(per_set, ends, anchors, path):
    L = ["# Best-of-N results", "",
         "Generated by `scripts/07_analyze_bon.py` from cached scores. Protocol: "
         "[docs/experiment_protocol.md](../../docs/experiment_protocol.md). Differences are against "
         "N = 1 on the same tiles, with 95 % paired bootstrap CIs. KID differences are ×10³ "
         "(full-sample unbiased MMD²).", ""]
    if ends:
        L += ["## Primary endpoints", "",
              "CLIP score (E1), N = 16 vs N = 1, Holm-corrected over verifier × set:", "",
              "| Set / rule | Δ CLIP [95 % CI] | p (bootstrap) | p (Holm) | Significant |",
              "| --- | --- | --- | --- | --- |"]
        for k, v in ends["primary_clip_n16_vs_n1"].items():
            L.append(f"| {k} | {_ci(v)} | {v['p']:.4f} | {v['p_holm']:.4f} | {'yes' if v['reject'] else 'no'} |")
        L += ["", "Guard: KID-DINOv2 (E5) at N = 16 non-inferior to N = 1 (upper CI < 10 % of KID at N = 1):", "",
              "| Set / rule | Δ KID-DINOv2 ×10³ [95 % CI] | Margin ×10³ | Non-inferior |",
              "| --- | --- | --- | --- |"]
        for k, g in ends["guard_kid_dino_n16_vs_n1"].items():
            L.append(f"| {k} | {_ci(g['diff'], 1e3, 3)} | {g['margin'] * 1e3:.3f} | {'yes' if g['non_inferior'] else 'no'} |")
        L.append("")

    for s, r in per_set.items():
        L += [f"## {s} ({r['tiles']} tiles × {r['samples_per_tile']} samples)", "",
              "| Rule | N | Δ CLIP | Δ LPIPS (lower better) | Δ SSIM | Δ KID-Inception ×10³ | Δ KID-DINOv2 ×10³ |",
              "| --- | --- | --- | --- | --- | --- | --- |"]
        for rule in RULES:
            for n, c in r["rules"][rule].items():
                if n == "1":
                    continue
                L.append(f"| {RULE_NAME[rule]} | {n} | {_ci(c['clip_cos']['diff_vs_n1'])} | "
                         f"{_ci(c['lpips']['diff_vs_n1'])} | {_ci(c['ssim']['diff_vs_n1'])} | "
                         f"{_ci(c['kid_inception']['diff_vs_n1'], 1e3, 3)} | {_ci(c['kid_dino']['diff_vs_n1'], 1e3, 3)} |")
        n1 = r["rules"]["v1"]["1"]
        L += ["", f"N = 1 (no selection): CLIP {n1['clip_cos']['mean']:.4f}, LPIPS {n1['lpips']['mean']:.4f}, "
                  f"SSIM {n1['ssim']['mean']:.4f}, KID-Inception ×10³ {r['n1_kid_full_sample']['kid_inception'] * 1e3:.3f}, "
                  f"KID-DINOv2 ×10³ {r['n1_kid_full_sample']['kid_dino'] * 1e3:.3f}.", "",
              "Oracle (best of N by the evaluator itself; an upper bound, not a method):", "",
              "| Metric | " + " | ".join(f"N={n}" for n in r["oracle"]["clip_cos"]) + " |",
              "| --- |" + " --- |" * len(r["oracle"]["clip_cos"])]
        for m, vals in r["oracle"].items():
            L.append(f"| {m} | " + " | ".join(f"{v:.4f}" for v in vals.values()) + " |")
        L += ["", "Spearman correlation between verifier and evaluator scores (pooled over all samples; "
                  "mean within tile):", "", "| Verifier ~ evaluator | Pooled | Within tile |", "| --- | --- | --- |"]
        for k, v in r["verifier_evaluator_spearman"].items():
            L.append(f"| {k} | {v['pooled']:.3f} | {v['within_tile_mean']:.3f} |")
        L += ["", "Verifier validity on real tiles (share of other captions ranked above the tile's own; 0.5 = chance):", ""]
        for k, v in r["verifier_validity_gt"].items():
            L.append(f"- {k}: {v['own_caption_rank_pct_mean']:.3f}")
        L.append("")

    if anchors:
        L += ["## Anchors", ""]
        for k, a in anchors.items():
            if k in ("provenance", "stop_rule"):
                continue
            L.append(f"**{k}**: {a.get('label', a.get('a', '') + ' vs ' + a.get('b', ''))}")
            L.append("")
            for m in ("clip_cos", "lpips", "ssim"):
                if m not in a:
                    continue
                x = a[m]
                if "diff" in x:
                    L.append(f"- {m}: {x['mean_a']:.4f} vs {x['mean_b']:.4f}, Δ {_ci(x['diff'])}")
                else:
                    L.append(f"- {m}: {x['mean']:.4f} [{x['ci_low']:.4f}, {x['ci_high']:.4f}], reference "
                             f"{x['reference']}, inside CI: {x['reference_inside_ci']}")
            if "pixels" in a:
                p = a["pixels"]
                L.append(f"- PSNR fp32 vs bf16, same noise: mean {p['psnr_db_mean']:.1f} dB, "
                         f"5th pct. {p['psnr_db_p05']:.1f} dB, min {p['psnr_db_min']:.1f} dB")
            L.append("")
        sr = anchors.get("stop_rule", {})
        L += [f"Stop rule ({sr.get('rule', '')}): **{'TRIGGERED' if sr.get('stop') else 'not triggered'}**", ""]
    open(path, "w").write("\n".join(L) + "\n")
